# Workboard

Requires Node.js 22.22.1. No external dependencies or installation step are needed.

Run `npm start` to listen on `0.0.0.0:8080`. Set `PORT` to change the port and
`DB_PATH` to select the persistent SQLite file (default: `./data/workboard.sqlite`).
The database directory is created automatically. Retain this file across restarts.

Example:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

Open `/` to create and open projects. `GET /health` returns `{"status":"ok"}`.
On a project page, create tasks, toggle completion, and filter by All, Open, or
Completed. Tasks belong to their project and retain their saved state on restart.
Priority filter offers All, Low, Normal, and High, and combines with Task filter.
Both filters start at All when opening a project and remain selected during task
edits. Completion and priority changes immediately update matching rows; filtering
preserves creation order and leaves saved data and completion summaries unchanged.
Both filters remain available in archived projects.
The project list defaults to Active; switch Project filter to Archived to open or
restore archived projects. Archiving preserves tasks and makes task creation and
completion read-only until restoration. Each row summarizes all completed tasks.
Existing databases are migrated automatically without changing project or task IDs.
Active project pages also support renaming. Names are trimmed; renaming preserves
the project URL, list order, tasks, and summary. Archived projects cannot be renamed
until restored.
Each task row supports renaming with a trimmed title. Renaming preserves task
ownership, order, completion, and summaries, and updates its completion label.
Archived projects disable task renaming until restored.
Each task has a saved priority: Low, Normal, or High. Each project's Default task
priority starts at Normal and is saved independently. New tasks inherit that saved
default; changing it leaves existing tasks and both selected filters unchanged.
Archived projects display their saved default but disable changes until restored.
Priority changes preserve task order, completion, ownership, and summaries;
renaming preserves priority. Archived projects disable priority edits until restored.
Run `npm test` for HTTP integration tests, including persistence across separate
server processes. Tests use temporary databases and clean them up afterward.
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/task-filters.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-filters.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

async function readJson(request) {
  const chunks = [];
  let bodySize = 0;
  for await (const chunk of request) {
    bodySize += chunk.length;
    if (bodySize > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

export function createApplication(dbPath) {
  mkdirSync(dirname(dbPath), { recursive: true });
  const database = new DatabaseSync(dbPath);
  database.exec(`CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0)
  )`);
  database.exec(`PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id)`);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'defaultTaskPriority')) {
    database.exec("ALTER TABLE projects ADD COLUMN defaultTaskPriority TEXT NOT NULL DEFAULT 'Normal' CHECK (defaultTaskPriority IN ('Low', 'Normal', 'High'))");
  }
  const projectQuery = `SELECT projects.id, projects.name, projects.archived, projects.defaultTaskPriority,
    COUNT(tasks.id) AS totalCount, COALESCE(SUM(tasks.completed), 0) AS completedCount
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id`;
  const listProjects = database.prepare(`${projectQuery} GROUP BY projects.id ORDER BY projects.id`);
  const getProject = database.prepare(`${projectQuery} WHERE projects.id = ? GROUP BY projects.id`);
  const archiveProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const updateDefaultTaskPriority = database.prepare('UPDATE projects SET defaultTaskPriority = ? WHERE id = ?');
  const projectData = (project) => ({ ...project, archived: Boolean(project.archived) });
  const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const listTasks = database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id');
  const getTask = database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
  const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
  const taskData = (task) => ({ ...task, completed: Boolean(task.completed) });

  function json(response, status, value) {
    response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
    response.end(JSON.stringify(value));
  }

  const server = createServer(async (request, response) => {
    try {
      const pathname = new URL(request.url, 'http://localhost').pathname;
      if (request.method === 'GET' && pathname === '/health') {
        return json(response, 200, { status: 'ok' });
      }
      if (pathname === '/api/projects' && request.method === 'GET') {
        return json(response, 200, listProjects.all().map(projectData));
      }
      if (pathname === '/api/projects' && request.method === 'POST') {
        const input = await readJson(request);
        const name = typeof input?.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        const result = insertProject.run(name);
        return json(response, 201, projectData(getProject.get(Number(result.lastInsertRowid))));
      }
      const tasksMatch = pathname.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
      if (tasksMatch) {
        const projectId = Number(tasksMatch[1]);
        if (!getProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
        const taskId = tasksMatch[2] ? Number(tasksMatch[2]) : null;
        if (request.method === 'GET' && taskId === null) {
          return json(response, 200, listTasks.all(projectId).map(taskData));
        }
        if (request.method === 'POST' && taskId === null) {
          const input = await readJson(request);
          const project = getProject.get(projectId);
          if (project.archived) return json(response, 409, { error: 'Archived project is read-only' });
          const title = typeof input?.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          const result = insertTask.run(projectId, title, project.defaultTaskPriority);
          return json(response, 201, taskData(getTask.get(projectId, Number(result.lastInsertRowid))));
        }
        if (request.method === 'PATCH' && taskId !== null) {
          if (!getTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
          const input = await readJson(request);
          if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
          const fields = ['title', 'completed', 'priority'].filter((field) => Object.hasOwn(input ?? {}, field));
          if (fields.length > 1) {
            return json(response, 400, { error: 'Update title, completion, or priority separately' });
          }
          if (Object.hasOwn(input ?? {}, 'title')) {
            const title = typeof input.title === 'string' ? input.title.trim() : '';
            if (!title) return json(response, 400, { error: 'Task title is required' });
            renameTask.run(title, projectId, taskId);
          } else if (Object.hasOwn(input ?? {}, 'priority')) {
            if (!['Low', 'Normal', 'High'].includes(input.priority)) {
              return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
            }
            updateTaskPriority.run(input.priority, projectId, taskId);
          } else {
            if (typeof input?.completed !== 'boolean') {
              return json(response, 400, { error: 'Completion must be a boolean' });
            }
            updateTask.run(Number(input.completed), projectId, taskId);
          }
          return json(response, 200, taskData(getTask.get(projectId, taskId)));
        }
      }
      const projectMatch = pathname.match(/^\/api\/projects\/([1-9]\d*)$/);
      if (request.method === 'PATCH' && projectMatch) {
        const projectId = Number(projectMatch[1]);
        if (!getProject.get(projectId)) return json(response, 404, { error: 'Project not found' });
        const input = await readJson(request);
        const fields = ['name', 'archived', 'defaultTaskPriority'].filter((field) => Object.hasOwn(input ?? {}, field));
        if (fields.length > 1) {
          return json(response, 400, { error: 'Update name, archive state, or default task priority separately' });
        }
        if (Object.hasOwn(input ?? {}, 'name')) {
          if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, projectId);
        } else if (Object.hasOwn(input ?? {}, 'defaultTaskPriority')) {
          if (getProject.get(projectId).archived) return json(response, 409, { error: 'Archived project is read-only' });
          if (!['Low', 'Normal', 'High'].includes(input.defaultTaskPriority)) {
            return json(response, 400, { error: 'Default task priority must be Low, Normal, or High' });
          }
          updateDefaultTaskPriority.run(input.defaultTaskPriority, projectId);
        } else {
          if (typeof input?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archive state must be a boolean' });
          }
          archiveProject.run(Number(input.archived), projectId);
        }
        return json(response, 200, projectData(getProject.get(projectId)));
      }
      if (request.method === 'GET' && projectMatch) {
        const project = getProject.get(Number(projectMatch[1]));
        return project
          ? json(response, 200, projectData(project))
          : json(response, 404, { error: 'Project not found' });
      }
      if (request.method === 'GET') {
        const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(pathname) ? '/' : pathname);
        if (asset) {
          response.writeHead(200, { 'Content-Type': asset[0] });
          return response.end(asset[1]);
        }
      }
      json(response, 404, { error: 'Not found' });
    } catch (error) {
      if (error.status) return json(response, error.status, { error: error.message });
      console.error(error);
      if (!response.headersSent) json(response, 500, { error: 'Unable to complete the request' });
      else response.end();
    }
  });
  server.on('close', () => database.close());
  return server;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const server = createApplication(process.env.DB_PATH || './data/workboard.sqlite');
  server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
    console.log(`Workboard listening on port ${server.address().port}`);
  });
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.on(signal, () => server.close());
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

async function start(dbPath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timeout); reject(error); });
    child.once('exit', () => { clearTimeout(timeout); reject(new Error(errors)); });
    child.stdout.on('data', (chunk) => {
      const match = chunk.toString().match(/listening on port (\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
  });
  return {
    url: `http://127.0.0.1:${port}`,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('projects and owned tasks validate, preserve order, and survive a server-process restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const dbPath = join(directory, 'nested', 'projects.sqlite');
  let server;
  try {
    server = await start(dbPath);
    const health = await fetch(`${server.url}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const create = (name) => fetch(`${server.url}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    for (const name of ['', '  \t\n', null, 42]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(`${server.url}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<Second project>')).json();
    assert.notEqual(first.id, second.id);
    let expected = [first, second];
    assert.deepEqual(first, { id: first.id, name: 'First project', archived: false, defaultTaskPriority: 'Normal', totalCount: 0, completedCount: 0 });
    assert.deepEqual(await (await fetch(`${server.url}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${server.url}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`]) {
      const response = await fetch(`${server.url}${path}`);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<title>Workboard<\/title>/);
    }
    assert.equal((await fetch(`${server.url}/api/projects/999999`)).status, 404);
    const malformed = await fetch(`${server.url}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    const tasksPath = `/api/projects/${first.id}/tasks`;
    const otherTasksPath = `/api/projects/${second.id}/tasks`;
    const send = (path, method, body) => fetch(`${server.url}${path}`, {
      method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    });
    const list = async (path) => (await fetch(`${server.url}${path}`)).json();
    for (const title of ['', '  \t\n', null, 42]) {
      const response = await send(tasksPath, 'POST', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await list(tasksPath), []);
    const taskResponse = await send(tasksPath, 'POST', { title: '  First task  ' });
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const nextTask = await (await send(tasksPath, 'POST', { title: '<Next task>' })).json();
    const otherTask = await (await send(otherTasksPath, 'POST', { title: 'Other project task' })).json();
    assert.deepEqual(await list(tasksPath), [task, nextTask]);
    assert.deepEqual(await list(otherTasksPath), [otherTask]);
    assert.equal((await send(`${otherTasksPath}/${task.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await send('/api/projects/999999/tasks', 'POST', { title: 'Missing project' })).status, 404);
    for (const completed of ['true', 1, null]) {
      assert.equal((await send(`${tasksPath}/${task.id}`, 'PATCH', { completed })).status, 400);
    }
    assert.deepEqual(await list(tasksPath), [task, nextTask]);
    const completedResponse = await send(`${tasksPath}/${task.id}`, 'PATCH', { completed: true });
    assert.equal(completedResponse.status, 200);
    const completedTask = { ...task, completed: true };
    assert.deepEqual(await completedResponse.json(), completedTask);
    assert.deepEqual(await list(tasksPath), [completedTask, nextTask]);
    const firstWithTasks = { ...first, totalCount: 2, completedCount: 1 };
    expected = [firstWithTasks, { ...second, totalCount: 1 }];
    assert.deepEqual(await list('/api/projects'), expected);
    await server.stop();
    server = undefined;
    server = await start(dbPath);
    assert.deepEqual(await (await fetch(`${server.url}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${server.url}/api/projects/${first.id}`)).json(), firstWithTasks);
    assert.deepEqual(await list(tasksPath), [completedTask, nextTask]);
    assert.deepEqual(await list(otherTasksPath), [otherTask]);
    const projectPath = `/api/projects/${first.id}`;
    for (const archived of [null, 1, 'true']) {
      assert.equal((await send(projectPath, 'PATCH', { archived })).status, 400);
    }
    assert.equal((await send('/api/projects/999999', 'PATCH', { archived: true })).status, 404);
    const archivedProject = { ...firstWithTasks, archived: true };
    const archivedResponse = await send(projectPath, 'PATCH', { archived: true });
    assert.equal(archivedResponse.status, 200);
    assert.deepEqual(await archivedResponse.json(), archivedProject);
    await server.stop();
    server = undefined;
    server = await start(dbPath);
    assert.deepEqual(await list(projectPath), archivedProject);
    assert.deepEqual(await list('/api/projects'), [archivedProject, expected[1]]);
    assert.deepEqual(await list(tasksPath), [completedTask, nextTask]);
    assert.equal((await send(tasksPath, 'POST', { title: 'Blocked' })).status, 409);
    assert.equal((await send(`${tasksPath}/${task.id}`, 'PATCH', { completed: false })).status, 409);
    assert.deepEqual(await list(tasksPath), [completedTask, nextTask]);
    assert.deepEqual(await list(projectPath), archivedProject);
    assert.deepEqual(await (await send(projectPath, 'PATCH', { archived: false })).json(), firstWithTasks);
    await server.stop();
    server = undefined;
    server = await start(dbPath);
    assert.deepEqual(await list(projectPath), firstWithTasks);
    assert.deepEqual(await list(tasksPath), [completedTask, nextTask]);
    const reopened = await send(`${tasksPath}/${task.id}`, 'PATCH', { completed: false });
    assert.equal(reopened.status, 200);
    assert.deepEqual(await reopened.json(), task);
    await server.stop();
    server = undefined;
    server = await start(dbPath);
    assert.deepEqual(await list(tasksPath), [task, nextTask]);
    assert.deepEqual(await list(projectPath), { ...firstWithTasks, completedCount: 0 });
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});


test('renaming preserves project identity, order, tasks, summaries, and archived protection across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-rename-'));
